#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_H 10
#define MAX_W 10000

int H, W, K;
int board[MAX_H][MAX_W];
int temp[MAX_H][MAX_W];

// copy board to temp
void copy_board() {
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            temp[i][j] = board[i][j];
}

// simulate dropping stones after removal
void drop() {
    for (int j = 0; j < W; j++) {
        int write = H - 1;
        for (int i = H - 1; i >= 0; i--) {
            if (temp[i][j] != 0) {
                temp[write][j] = temp[i][j];
                if (write != i) temp[i][j] = 0;
                write--;
            }
        }
        for (int i = write; i >= 0; i--) temp[i][j] = 0;
    }
}

// simulate chain reaction starting from an empty cell (r,c), return score
int simulate(int r, int c) {
    copy_board();
    temp[r][c] = 0; // erase chosen cell
    drop();

    int total_score = 0;
    int chain = 0;
    int found = 1;

    while (found) {
        found = 0;
        int mark[MAX_H][MAX_W];
        memset(mark, 0, sizeof(mark));

        // find horizontal groups of K or more same digits
        for (int i = 0; i < H; i++) {
            int j = 0;
            while (j < W) {
                if (temp[i][j] == 0) { j++; continue; }
                int digit = temp[i][j];
                int start = j;
                while (j < W && temp[i][j] == digit) j++;
                int len = j - start;
                if (len >= K) {
                    for (int k = start; k < j; k++) mark[i][k] = 1;
                    found = 1;
                }
            }
        }

        if (!found) break;

        // calculate sum of disappearing stones and remove them
        int sum = 0;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (mark[i][j]) {
                    sum += temp[i][j];
                    temp[i][j] = 0;
                }
            }
        }
        total_score += sum * (1 << chain);
        chain++;
        drop();
    }
    return total_score;
}

