/* Remove all horizontal runs of length >= K with same digit.
   Returns the sum of removed digits in this single step.
   The board is modified: removed cells become 0, then gravity is applied. */
long long one_step(int b[MAXH][MAXW]) {
    int mark[MAXH][MAXW];
    memset(mark, 0, sizeof(mark));

    int r, c;
    for (r = 0; r < H; r++) {
        int start = 0;
        while (start < W) {
            if (b[r][start] == 0) {
                start++;
                continue;
            }
            int d = b[r][start];
            int end = start + 1;
            while (end < W && b[r][end] == d) end++;
            if (end - start >= K) {
                for (c = start; c < end; c++) mark[r][c] = 1;
            }
            start = end;
        }
    }

    long long sum = 0;
    int any = 0;
    for (r = 0; r < H; r++) {
        for (c = 0; c < W; c++) {
            if (mark[r][c]) {
                sum += b[r][c];
                b[r][c] = 0;
                any = 1;
            }
        }
    }
    if (!any) return 0;

    /* gravity */
    for (c = 0; c < W; c++) {
        int write = H - 1;
        for (r = H - 1; r >= 0; r--) {
            if (b[r][c] != 0) {
                b[write][c] = b[r][c];
                if (write != r) b[r][c] = 0;
                write--;
            }
        }
        while (write >= 0) {
            b[write][c] = 0;
            write--;
        }
    }

    return sum;
}

long long simulate_after_erase(int er, int ec) {
    int b[MAXH][MAXW];
    memcpy(b, A, sizeof(A));

    /* erase one cell */
    b[er][ec] = 0;

    /* gravity on that column */
    int c = ec;
    int write = H - 1;
    for (int r = H - 1; r >= 0; r--) {
        if (b[r][c] != 0) {
            b[write][c] = b[r][c];
            if (write != r) b[r][c] = 0;
            write--;
        }
    }
    while (write >= 0) {
        b[write][c] = 0;
        write--;
    }

    long long score = 0;
    long long mult = 1;
    while (1) {
        long long s = one_step(b);
        if (s == 0) break;
        score += s * mult;
        mult <<= 1;
    }
    return score;
}

int main(void) {
    if (scanf("%d %d %d", &H, &W, &K) != 3) return 0;

    for (int i = 0; i < H; i++) {
