int processBoard(vector<string>& b, int chain) {
    int score = 0;
    bool found = true;

    while (found) {
        found = false;
        vector<vector<bool>> toRemove(H, vector<bool>(W, false));

        // Find horizontal matches of K or more
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; ) {
                if (b[i][j] == '0') { j++; continue; }
                int len = 0;
                int start = j;
                while (j < W && b[i][j] == b[i][start]) {
                    if (b[i][j] != '0') len++;
                    j++;
                }
                if (len >= K) {
                    for (int k = start; k < j; k++) {
                        if (b[i][k] != '0') {
                            toRemove[i][k] = true;
                            found = true;
                        }
                    }
                }
            }
        }

        if (!found) break;

        // Remove matched stones and calculate score
        int removedSum = 0;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (toRemove[i][j]) {
                    removedSum += (b[i][j] - '0');
                    b[i][j] = '0';
                }
            }
        }

        score += removedSum * (1 << (chain - 1));
        chain++;

        // Drop stones down
        for (int j = 0; j < W; j++) {
            int write = H - 1;
            for (int i = H - 1; i >= 0; i--) {
                if (b[i][j] != '0') {
                    b[write][j] = b[i][j];
                    if (write != i) b[i][j] = '0';
                    write--;
                }
            }
            for (int i = write; i >= 0; i--) {
                b[i][j] = '0';
            }
        }
    }

    return score;
}

