                        cur[writeRow][c] = cur[r][c];
                        if (writeRow != r) cur[r][c] = 0;
                        writeRow--;
                    }
                }
                // Fill remaining rows with 0
                for (int r = writeRow; r >= 0; r--) {
                    cur[r][c] = 0;
                }
            }
        }
        return totalScore;
    }
}

import java.util.*;

public class Main {
    static int H, W, K;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt(); W = sc.nextInt(); K = sc.nextInt();
        int[][] board = new int[H][W];
        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++)
                board[i][j] = sc.nextInt();

        long maxScore = 0;
        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                int[][] b = copy(board);
                b[r][c] = 0;
                long score = simulate(b);
                maxScore = Math.max(maxScore, score);
            }
        }
        System.out.println(maxScore);
    }

    static long simulate(int[][] board) {
        applyGravity(board);
        long totalScore = 0;
        int chain = 0;
        while (true) {
            boolean[][] toRemove = new boolean[H][W];
            boolean found = false;
            for (int r = 0; r < H; r++) {
                int c = 0;
                while (c < W) {
                    if (board[r][c] == 0) { c++; continue; }
                    int d = board[r][c];
                    int start = c;
                    while (c < W && board[r][c] == d) c++;
                    if (c - start >= K) {
                        found = true;
                        for (int j = start; j < c; j++) toRemove[r][j] = true;
                    }
                }
            }
            if (!found) break;
            chain++;
            long mult = 1L << (chain - 1);
            long chainSum = 0;
            for (int r = 0; r < H; r++)
                for (int c = 0; c < W; c++)
                    if (toRemove[r][c]) { chainSum += board[r][c]; board[r][c] = 0; }
            totalScore += mult * chainSum;
            applyGravity(board);
        }
        return totalScore;
    }

    static void applyGravity(int[][] board) {
        for (int c = 0; c < W; c++) {
            int[] col = new int[H];
            int idx = H - 1;
            for (int r = H - 1; r >= 0; r--) {
                if (board[r][c] != 0) col[idx--] = board[r][c];
            }
            for (int r = 0; r <= idx; r++) col[r] = 0;
            for (int r = 0; r < H; r++) board[r][c] = col[r];
        }
    }

    static int[][] copy(int[][] b) {
        int[][] c = new int[H][W];
        for (int i = 0; i < H; i++) c[i] = b[i].clone();
        return c;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int H, W, K;
    static int[][] original;

    static long simulateErase(int eraseR, int eraseC) {
        int[][] b = new int[H][W];
        for (int i = 0; i < H; i++) b[i] = original[i].clone();

        // erase one cell, then gravity
        for (int r = eraseR; r > 0; r--) b[r][eraseC] = b[r - 1][eraseC];
        b[0][eraseC] = 0;

        long score = 0;
        long mul = 1;

        while (true) {
            boolean[][] del = new boolean[H][W];
            boolean any = false;
            long roundSum = 0;

            for (int i = 0; i < H; i++) {
                int j = 0;
                while (j < W) {
                    if (b[i][j] == 0) {
                        j++;
                        continue;
                    }
                    int d = b[i][j];
                    int start = j;
                    while (j < W && b[i][j] == d) j++;
                    int len = j - start;
                    if (len >= K) {
                        any = true;
                        for (int c = start; c < j; c++) {
                            del[i][c] = true;
                            roundSum += d;
                        }
                    }
                }
            }

            if (!any) break;
            score += roundSum * mul;

            // gravity by column
            for (int c = 0; c < W; c++) {
                int write = H - 1;
                for (int r = H - 1; r >= 0; r--) {
                    if (!del[r][c] && b[r][c] != 0) {
                        b[write][c] = b[r][c];
                        write--;
                    }
                }
                while (write >= 0) {
                    b[write][c] = 0;
                    write--;
                }
            }

            mul <<= 1;
        }

        return score;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        H = fs.nextInt();
        while (H != 0) {
            W = fs.nextInt();
            K = fs.nextInt();

            original = new int[H][W];
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    original[i][j] = fs.nextInt();
                }
            }

            long ans = 0;
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    ans = Math.max(ans, simulateErase(i, j));
                }
            }

            System.out.println(ans);
            H = fs.nextInt();
        }
    }
}
